CREATE OR REPLACE FUNCTION public.combat2_authoritative_arrival_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_seed text; v_request uuid; v_result jsonb;
BEGIN
  IF OLD.current_node_id IS NOT DISTINCT FROM NEW.current_node_id OR NEW.hp<=0
     OR COALESCE(current_setting('app.combat2_depart_authorized',true),'')<>'true' THEN
    RETURN NEW;
  END IF;
  v_seed:=md5(NEW.id::text||':'||OLD.current_node_id::text||':'||NEW.current_node_id::text||':'||txid_current()::text);
  v_request:=(substr(v_seed,1,8)||'-'||substr(v_seed,9,4)||'-4'||substr(v_seed,14,3)||'-8'||substr(v_seed,18,3)||'-'||substr(v_seed,21,12))::uuid;
  v_result:=public.combat2_arrive_after_relocation(NEW.id,v_request);
  IF v_result->>'ok'='false' AND v_result->>'kind' NOT IN ('no_engagement','mode_refused','already_present') THEN
    RAISE EXCEPTION 'ENG-COMBAT-002 arrival failed closed: %',v_result->>'kind';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_bind_test_encounter()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_arena uuid;
BEGIN
 IF TG_OP='INSERT' OR (OLD.status IS DISTINCT FROM 'active' AND NEW.status='active') THEN
  SELECT n.arena_id INTO v_arena FROM public.combat2_test_arena_node n
  JOIN public.combat2_test_arena a ON a.id=n.arena_id
  WHERE n.node_id=NEW.node_id AND n.active AND a.active;
  NEW.test_arena_id:=v_arena;
 ELSIF NEW.test_arena_id IS DISTINCT FROM OLD.test_arena_id THEN
  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='test_arena_identity_immutable';
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.combat2_guard_test_arena_location()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE old_test boolean; new_test boolean; approved boolean;
BEGIN
 IF OLD.current_node_id IS NOT DISTINCT FROM NEW.current_node_id THEN RETURN NEW; END IF;
 SELECT EXISTS(SELECT 1 FROM public.combat2_test_arena_node WHERE node_id=OLD.current_node_id) INTO old_test;
 SELECT EXISTS(SELECT 1 FROM public.combat2_test_arena_node WHERE node_id=NEW.current_node_id) INTO new_test;
 IF NOT old_test AND NOT new_test THEN RETURN NEW; END IF;
 approved:=COALESCE(current_setting('app.combat2_depart_authorized',true),'')='true'
   OR COALESCE(current_setting('app.combat2_test_relocate_authorized',true),'')='true'
   OR COALESCE(current_setting('app.combat2_respawn_authorized',true),'')='true';
 IF NOT approved THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='test_arena_relocation_required'; END IF;
 IF auth.role()='service_role' THEN RETURN NEW; END IF;
 IF auth.uid() IS NULL OR NEW.user_id IS DISTINCT FROM auth.uid() THEN
  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='test_arena_not_authorized'; END IF;
 IF new_test AND NOT public.combat2_test_arena_access_allowed(auth.uid(),NEW.id,NEW.current_node_id) THEN
  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='test_arena_not_authorized'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.combat2_party_tank_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_encounter uuid;
BEGIN
  FOR v_encounter IN SELECT DISTINCT g.encounter_id FROM public.node_arrival_group g
    WHERE g.party_id = NEW.id AND g.active LOOP
    UPDATE public.node_encounter SET state_version = state_version + 1,
      claim_token = NULL, claimed_tick = NULL, claim_expires_at = NULL, updated_at = now()
      WHERE id = v_encounter;
    PERFORM public.combat2_refresh_tanks(v_encounter);
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.combat_enter_without_canary_gate(_character_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  prior public.node_pending_event; e public.node_encounter; f public.node_fighter;
  v_node uuid; v_check uuid; v_party uuid; v_group uuid; v_fighter uuid;
  v_seq bigint; v_generation bigint; v_event uuid; v_version bigint;
  v_parties uuid[];
  v_reentry boolean := false; v_reactivated boolean := false;
BEGIN
  IF NOT public.combat_mode_is_open() THEN RETURN jsonb_build_object('ok',false,'kind','mode_refused','reason','maintenance'); END IF;
  IF _request_id IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','invalid_request','reason','request_id_required'); END IF;
  IF NOT public.owns_character(_character_id) THEN RETURN jsonb_build_object('ok',false,'kind','not_authorized','reason','character'); END IF;
  SELECT * INTO prior FROM public.node_pending_event WHERE request_id = _request_id;
  IF FOUND THEN
    IF prior.actor_character_id IS DISTINCT FROM _character_id OR prior.event_type <> 'fighter_entered' THEN
      RETURN jsonb_build_object('ok',false,'kind','invalid_request','reason','request_id_conflict');
    END IF;
    RETURN jsonb_build_object('ok',true,'kind','already_entered','encounter_id',prior.encounter_id,
      'event_id',prior.id,'fighter_id',prior.payload->>'fighter_id','entry_seq',(prior.payload->>'entry_seq')::bigint);
  END IF;
  SELECT current_node_id INTO v_node FROM public.characters WHERE id = _character_id;
  IF v_node IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','no_node'); END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('combat_enter_node:' || v_node::text,0));
  SELECT current_node_id INTO v_check FROM public.characters WHERE id = _character_id;
  IF v_check IS DISTINCT FROM v_node THEN RETURN jsonb_build_object('ok',false,'kind','node_changed'); END IF;
  IF NOT EXISTS (SELECT 1 FROM public.creatures WHERE node_id=v_node AND is_alive) THEN
    RETURN jsonb_build_object('ok',false,'kind','no_living_creatures');
  END IF;
  SELECT array_agg(pm.party_id) INTO v_parties FROM public.party_members pm
    WHERE pm.character_id=_character_id AND pm.status='accepted';
  IF cardinality(v_parties) > 1 THEN
    RETURN jsonb_build_object('ok',false,'kind','ambiguous_party_membership');
  END IF;
  v_party := v_parties[1];
  SELECT * INTO e FROM public.node_encounter WHERE node_id=v_node FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.node_encounter(node_id,status,next_due_at) VALUES(v_node,'active',now()) RETURNING * INTO e;
  ELSIF e.status <> 'active' THEN
    v_reactivated := true;
    UPDATE public.node_fighter SET present=false,left_at=COALESCE(left_at,now()),updated_at=now() WHERE encounter_id=e.id AND present;
    UPDATE public.node_arrival_group SET active=false,deactivated_at=now() WHERE encounter_id=e.id AND active;
    UPDATE public.node_creature SET tank_fighter_id=NULL,engaged=false,updated_at=now() WHERE encounter_id=e.id AND is_alive;
    UPDATE public.node_intent SET status='rejected',reject_reason='stale_generation'
      WHERE encounter_id=e.id AND status='pending';
    UPDATE public.node_pending_event SET consumed_at=now(),consumed_tick=e.tick
      WHERE encounter_id=e.id AND consumed_at IS NULL;
    UPDATE public.node_encounter SET status='active',next_due_at=now(),claim_token=NULL,claimed_tick=NULL,
      claim_expires_at=NULL,intent_cutoff_seq=NULL,updated_at=now() WHERE id=e.id RETURNING * INTO e;
  END IF;
  PERFORM public.combat2_seed_spawns(e.id, v_node);
  IF v_party IS NULL THEN
    SELECT COALESCE(MAX(g.generation),0)+1 INTO v_generation FROM public.node_arrival_group g
      WHERE g.encounter_id=e.id AND g.party_id IS NULL;
    INSERT INTO public.node_arrival_group(encounter_id,party_id,generation)
      VALUES(e.id,NULL,v_generation) RETURNING id INTO v_group;
  ELSE
    SELECT g.id INTO v_group FROM public.node_arrival_group g
      WHERE g.encounter_id=e.id AND g.party_id=v_party AND g.active LIMIT 1;
    IF v_group IS NULL THEN
      SELECT COALESCE(MAX(g.generation),0)+1 INTO v_generation FROM public.node_arrival_group g
        WHERE g.encounter_id=e.id AND g.party_id=v_party;
      INSERT INTO public.node_arrival_group(encounter_id,party_id,generation)
        VALUES(e.id,v_party,v_generation) RETURNING id INTO v_group;
    END IF;
  END IF;
  SELECT nf.* INTO f FROM public.node_fighter nf WHERE nf.encounter_id=e.id AND nf.character_id=_character_id FOR UPDATE;
  IF FOUND AND f.present THEN
    RETURN jsonb_build_object('ok',false,'kind','already_present','encounter_id',e.id,'fighter_id',f.id,'entry_seq',f.entry_seq);
  END IF;
  v_seq := nextval('node_fighter_entry_seq_seq');
  IF FOUND THEN
    v_reentry := true;
    UPDATE public.node_fighter SET present=true,left_at=NULL,entry_seq=v_seq,joined_at=now(),party_id_at_entry=v_party,
      arrival_group_id=v_group,exit_request_id=NULL,updated_at=now() WHERE id=f.id RETURNING id INTO v_fighter;
  ELSE
    INSERT INTO public.node_fighter(encounter_id,character_id,entry_seq,present,party_id_at_entry,joined_at,arrival_group_id)
      VALUES(e.id,_character_id,v_seq,true,v_party,now(),v_group) RETURNING id INTO v_fighter;
  END IF;
  UPDATE public.node_creature nc SET engaged=true,updated_at=now()
    FROM public.creatures cr WHERE nc.encounter_id=e.id AND nc.creature_id=cr.id AND nc.is_alive
      AND cr.is_aggressive=true AND NOT nc.engaged;
  PERFORM public.combat2_refresh_tanks(e.id);
  INSERT INTO public.node_pending_event(encounter_id,event_type,actor_character_id,payload,request_id)
    VALUES(e.id,'fighter_entered',_character_id,jsonb_build_object('fighter_id',v_fighter,'node_id',v_node,
      'entry_seq',v_seq,'arrival_group_id',v_group,'reentry',v_reentry,'reactivated',v_reactivated),_request_id)
    RETURNING id INTO v_event;
  UPDATE public.node_encounter SET state_version=state_version+1,claim_token=NULL,claimed_tick=NULL,
    claim_expires_at=NULL,updated_at=now() WHERE id=e.id RETURNING state_version INTO v_version;
  RETURN jsonb_build_object('ok',true,'kind',CASE WHEN v_reentry THEN 'reentered' ELSE 'entered' END,
    'encounter_id',e.id,'node_id',v_node,'reactivated',v_reactivated,'fighter_id',v_fighter,
    'entry_seq',v_seq,'event_id',v_event,'state_version',v_version);
END;
$function$

CREATE OR REPLACE FUNCTION public.combat_enter_without_engagement_gate(_character_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE node_id uuid;
BEGIN
  SELECT current_node_id INTO node_id FROM public.characters WHERE id=_character_id;
  IF NOT public.combat2_node_runtime_eligible(node_id) THEN
    RETURN jsonb_build_object('ok',false,'kind','scope_refused','reason','node_not_enabled');
  END IF;
  RETURN public.combat_enter_without_canary_gate(_character_id,_request_id);
END $function$

CREATE OR REPLACE FUNCTION public.combat_enter(_character_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_node uuid;
BEGIN
  IF NOT public.combat_mode_is_open() THEN
    RETURN jsonb_build_object('ok', false, 'kind', 'mode_refused', 'reason', 'maintenance');
  END IF;
  IF _request_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'kind', 'invalid_request', 'reason', 'request_id_required');
  END IF;
  IF NOT public.owns_character(_character_id) THEN
    RETURN jsonb_build_object('ok', false, 'kind', 'not_authorized', 'reason', 'character');
  END IF;
  SELECT current_node_id INTO v_node
  FROM public.characters
  WHERE id = _character_id;

  IF NOT EXISTS (
    SELECT 1
    FROM public.creatures c
    WHERE c.node_id = v_node
      AND c.is_alive
      AND c.is_aggressive
  ) AND NOT EXISTS (
    SELECT 1
    FROM public.node_encounter e
    JOIN public.node_creature nc ON nc.encounter_id = e.id
    WHERE e.node_id = v_node
      AND e.status = 'active'
      AND nc.is_alive
      AND nc.engaged
  ) THEN
    RETURN jsonb_build_object('ok', false, 'kind', 'no_engagement');
  END IF;

  RETURN public.combat_enter_without_engagement_gate(_character_id, _request_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_arrive_after_relocation(_character_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  prior public.node_pending_event; e public.node_encounter; f public.node_fighter;
  v_node uuid; v_check uuid; v_party uuid; v_group uuid; v_fighter uuid;
  v_seq bigint; v_generation bigint; v_event uuid; v_version bigint;
  v_parties uuid[]; v_reentry boolean:=false; v_reactivated boolean:=false;
BEGIN
  IF COALESCE(current_setting('app.combat2_depart_authorized',true),'')<>'true' THEN
    RETURN jsonb_build_object('ok',false,'kind','not_authorized');
  END IF;
  IF NOT public.combat_mode_is_open() THEN
    RETURN jsonb_build_object('ok',false,'kind','mode_refused','reason','maintenance');
  END IF;
  IF _request_id IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','invalid_request'); END IF;
  SELECT * INTO prior FROM public.node_pending_event WHERE request_id=_request_id;
  IF FOUND THEN
    IF prior.actor_character_id IS DISTINCT FROM _character_id OR prior.event_type<>'fighter_entered' THEN
      RETURN jsonb_build_object('ok',false,'kind','invalid_request','reason','request_id_conflict');
    END IF;
    RETURN jsonb_build_object('ok',true,'kind','already_entered','encounter_id',prior.encounter_id,
      'event_id',prior.id,'fighter_id',prior.payload->>'fighter_id','entry_seq',(prior.payload->>'entry_seq')::bigint);
  END IF;

  SELECT current_node_id INTO v_node FROM public.characters WHERE id=_character_id AND hp>0;
  IF v_node IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','not_living_at_node'); END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('combat_enter_node:'||v_node::text,0));
  SELECT current_node_id INTO v_check FROM public.characters WHERE id=_character_id AND hp>0 FOR UPDATE;
  IF v_check IS DISTINCT FROM v_node THEN RETURN jsonb_build_object('ok',false,'kind','node_changed'); END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.creatures c
    WHERE c.node_id=v_node AND c.is_alive AND c.is_aggressive
  ) AND NOT EXISTS (
    SELECT 1 FROM public.node_encounter active_e
    JOIN public.node_creature active_nc ON active_nc.encounter_id=active_e.id
    WHERE active_e.node_id=v_node AND active_e.status='active'
      AND active_nc.is_alive AND active_nc.engaged
  ) THEN
    RETURN jsonb_build_object('ok',false,'kind','no_engagement');
  END IF;

  SELECT array_agg(pm.party_id ORDER BY pm.party_id) INTO v_parties
  FROM public.party_members pm WHERE pm.character_id=_character_id AND pm.status='accepted';
  IF cardinality(v_parties)>1 THEN
    RAISE EXCEPTION 'ENG-COMBAT-002: ambiguous accepted party membership for %',_character_id;
  END IF;
  v_party:=v_parties[1];

  SELECT * INTO e FROM public.node_encounter WHERE node_id=v_node FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.node_encounter(node_id,status,next_due_at)
      VALUES(v_node,'active',now()) RETURNING * INTO e;
  ELSIF e.status<>'active' THEN
    v_reactivated:=true;
    UPDATE public.node_fighter SET present=false,left_at=COALESCE(left_at,now()),updated_at=now()
      WHERE encounter_id=e.id AND present;
    UPDATE public.node_arrival_group SET active=false,deactivated_at=now()
      WHERE encounter_id=e.id AND active;
    UPDATE public.node_creature SET tank_fighter_id=NULL,engaged=false,updated_at=now()
      WHERE encounter_id=e.id AND is_alive;
    UPDATE public.node_intent SET status='rejected',reject_reason='stale_generation'
      WHERE encounter_id=e.id AND status='pending';
    UPDATE public.node_pending_event SET consumed_at=now(),consumed_tick=e.tick
      WHERE encounter_id=e.id AND consumed_at IS NULL;
    UPDATE public.node_encounter SET status='active',next_due_at=now(),claim_token=NULL,
      claimed_tick=NULL,claim_expires_at=NULL,intent_cutoff_seq=NULL,updated_at=now()
      WHERE id=e.id RETURNING * INTO e;
  END IF;
  PERFORM public.combat2_seed_spawns(e.id,v_node);

  IF v_party IS NULL THEN
    SELECT COALESCE(MAX(g.generation),0)+1 INTO v_generation
      FROM public.node_arrival_group g WHERE g.encounter_id=e.id AND g.party_id IS NULL;
    INSERT INTO public.node_arrival_group(encounter_id,party_id,generation)
      VALUES(e.id,NULL,v_generation) RETURNING id INTO v_group;
  ELSE
    SELECT g.id INTO v_group FROM public.node_arrival_group g
      WHERE g.encounter_id=e.id AND g.party_id=v_party AND g.active
      ORDER BY g.arrival_seq DESC,g.id DESC LIMIT 1;
    IF v_group IS NULL THEN
      SELECT COALESCE(MAX(g.generation),0)+1 INTO v_generation
        FROM public.node_arrival_group g WHERE g.encounter_id=e.id AND g.party_id=v_party;
      INSERT INTO public.node_arrival_group(encounter_id,party_id,generation)
        VALUES(e.id,v_party,v_generation) RETURNING id INTO v_group;
    END IF;
  END IF;

  SELECT nf.* INTO f FROM public.node_fighter nf
    WHERE nf.encounter_id=e.id AND nf.character_id=_character_id FOR UPDATE;
  IF FOUND AND f.present THEN
    RETURN jsonb_build_object('ok',false,'kind','already_present','encounter_id',e.id,
      'fighter_id',f.id,'entry_seq',f.entry_seq);
  END IF;
  v_seq:=nextval('node_fighter_entry_seq_seq');
  IF FOUND THEN
    v_reentry:=true;
    UPDATE public.node_fighter SET present=true,left_at=NULL,entry_seq=v_seq,joined_at=now(),
      party_id_at_entry=v_party,arrival_group_id=v_group,exit_request_id=NULL,updated_at=now()
      WHERE id=f.id RETURNING id INTO v_fighter;
  ELSE
    INSERT INTO public.node_fighter(encounter_id,character_id,entry_seq,present,party_id_at_entry,joined_at,arrival_group_id)
      VALUES(e.id,_character_id,v_seq,true,v_party,now(),v_group) RETURNING id INTO v_fighter;
  END IF;
  UPDATE public.node_creature nc SET engaged=true,updated_at=now()
    FROM public.creatures cr
    WHERE nc.encounter_id=e.id AND nc.creature_id=cr.id AND nc.is_alive
      AND cr.is_aggressive AND NOT nc.engaged;
  PERFORM public.combat2_refresh_tanks(e.id);
  INSERT INTO public.node_pending_event(encounter_id,event_type,actor_character_id,payload,request_id)
    VALUES(e.id,'fighter_entered',_character_id,jsonb_build_object('fighter_id',v_fighter,'node_id',v_node,
      'entry_seq',v_seq,'arrival_group_id',v_group,'reentry',v_reentry,'reactivated',v_reactivated),_request_id)
    RETURNING id INTO v_event;
  UPDATE public.node_encounter SET state_version=state_version+1,claim_token=NULL,claimed_tick=NULL,
    claim_expires_at=NULL,intent_cutoff_seq=NULL,updated_at=now()
    WHERE id=e.id RETURNING state_version INTO v_version;
  RETURN jsonb_build_object('ok',true,'kind',CASE WHEN v_reentry THEN 'reentered' ELSE 'entered' END,
    'encounter_id',e.id,'node_id',v_node,'reactivated',v_reactivated,'fighter_id',v_fighter,
    'entry_seq',v_seq,'event_id',v_event,'state_version',v_version);
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_authoritative_arrival_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_seed text; v_request uuid; v_result jsonb;
BEGIN
  IF OLD.current_node_id IS NOT DISTINCT FROM NEW.current_node_id OR NEW.hp<=0
     OR COALESCE(current_setting('app.combat2_depart_authorized',true),'')<>'true' THEN
    RETURN NEW;
  END IF;
  v_seed:=md5(NEW.id::text||':'||OLD.current_node_id::text||':'||NEW.current_node_id::text||':'||txid_current()::text);
  v_request:=(substr(v_seed,1,8)||'-'||substr(v_seed,9,4)||'-4'||substr(v_seed,14,3)||'-8'||substr(v_seed,18,3)||'-'||substr(v_seed,21,12))::uuid;
  v_result:=public.combat2_arrive_after_relocation(NEW.id,v_request);
  IF v_result->>'ok'='false' AND v_result->>'kind' NOT IN ('no_engagement','mode_refused','already_present') THEN
    RAISE EXCEPTION 'ENG-COMBAT-002 arrival failed closed: %',v_result->>'kind';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_depart_without_canary_gate(_character_id uuid, _destination_node_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_prior public.combat2_departure_request;
  v_character public.characters;
  v_encounter public.node_encounter;
  v_fighter public.node_fighter;
  v_connection jsonb;
  v_cost integer;
  v_capacity integer;
  v_bag numeric;
  v_event uuid;
  v_version bigint;
  v_origin uuid;
BEGIN
  IF _character_id IS NULL OR _destination_node_id IS NULL OR _request_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'kind','invalid_request');
  END IF;
  IF NOT public.owns_character(_character_id) THEN
    RETURN jsonb_build_object('ok',false,'kind','not_authorized');
  END IF;


  IF EXISTS(SELECT 1 FROM public.party_members pm JOIN public.parties p ON p.id=pm.party_id
    WHERE pm.character_id=_character_id AND pm.status='accepted' AND pm.is_following AND p.leader_id<>_character_id)
   THEN RETURN jsonb_build_object('ok',false,'kind','following_leader'); END IF;

  -- Lock order: request advisory -> origin-node advisory -> encounter -> character.
  -- This matches combat_enter's node advisory and node_tick_commit's encounter-first order.
  PERFORM pg_advisory_xact_lock(hashtextextended('combat2_depart_request:' || _request_id::text,0));

  SELECT * INTO v_prior FROM public.combat2_departure_request WHERE request_id = _request_id;
  IF FOUND THEN
    IF v_prior.character_id IS DISTINCT FROM _character_id
       OR v_prior.destination_node_id IS DISTINCT FROM _destination_node_id THEN
      RETURN jsonb_build_object('ok',false,'kind','request_id_conflict');
    END IF;
    RETURN jsonb_build_object('ok',true,
      'kind',CASE v_prior.status WHEN 'queued' THEN 'already_queued' WHEN 'moved' THEN 'already_moved' ELSE 'dead' END,
      'request_id',v_prior.request_id,'origin_node_id',v_prior.origin_node_id,
      'destination_node_id',v_prior.destination_node_id,'cost',v_prior.cost,'resource_kind',v_prior.resource_kind);
  END IF;

  SELECT * INTO v_character FROM public.characters WHERE id = _character_id;
  IF NOT FOUND OR v_character.current_node_id IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','stale_origin'); END IF;
  v_origin := v_character.current_node_id;
  PERFORM pg_advisory_xact_lock(hashtextextended('combat_enter_node:' || v_origin::text,0));
  PERFORM 1 FROM public.node_encounter
    WHERE node_id IN (v_origin,_destination_node_id) ORDER BY id FOR UPDATE;
  SELECT * INTO v_encounter FROM public.node_encounter
    WHERE node_id = v_origin AND status = 'active' FOR UPDATE;
  SELECT * INTO v_character FROM public.characters WHERE id = _character_id FOR UPDATE;
  IF v_character.current_node_id IS DISTINCT FROM v_origin THEN RETURN jsonb_build_object('ok',false,'kind','stale_origin'); END IF;
  IF v_character.hp <= 0 THEN RETURN jsonb_build_object('ok',false,'kind','dead'); END IF;
  IF _destination_node_id = v_character.current_node_id OR NOT EXISTS (SELECT 1 FROM public.nodes WHERE id=_destination_node_id) THEN
    RETURN jsonb_build_object('ok',false,'kind','invalid_destination');
  END IF;

  SELECT conn INTO v_connection FROM public.nodes n
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(n.connections,'[]'::jsonb)) conn
  WHERE n.id=v_character.current_node_id AND conn->>'node_id'=_destination_node_id::text LIMIT 1;
  IF v_connection IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','not_adjacent'); END IF;
  IF COALESCE((v_connection->>'hidden')::boolean,false) AND NOT public.hidden_connection_is_open(
    v_character.current_node_id,_destination_node_id,v_connection->>'direction') THEN
    RETURN jsonb_build_object('ok',false,'kind','unsupported_transition','reason','hidden');
  END IF;
  IF COALESCE(v_connection->>'direction','') = '' THEN
    RETURN jsonb_build_object('ok',false,'kind','unsupported_transition','reason','missing_direction');
  END IF;
  IF COALESCE((v_connection->>'locked')::boolean,false) AND NOT EXISTS (
    SELECT 1 FROM public.character_inventory ci JOIN public.items i ON i.id=ci.item_id
    WHERE ci.character_id=_character_id AND lower(i.name)=lower(COALESCE(v_connection->>'lock_key',''))
  ) THEN RETURN jsonb_build_object('ok',false,'kind','locked'); END IF;

  v_capacity := GREATEST(12 + FLOOR((COALESCE(v_character.str,10)-10)/2.0)::int,10);
  SELECT COALESCE(SUM(CASE WHEN i.item_type='consumable' THEN 1.0/3.0 ELSE 1.0 END),0)
    INTO v_bag FROM public.character_inventory ci JOIN public.items i ON i.id=ci.item_id
    WHERE ci.character_id=_character_id AND ci.equipped_slot IS NULL;
  v_cost := 5 + GREATEST(0,CEIL(v_bag)::int-v_capacity)*3;
  IF COALESCE(v_character.mp,0) < v_cost THEN RETURN jsonb_build_object('ok',false,'kind','insufficient_resource','resource_kind','mp'); END IF;

  IF v_encounter.id IS NOT NULL THEN
    SELECT * INTO v_fighter FROM public.node_fighter
      WHERE encounter_id=v_encounter.id AND character_id=_character_id AND present FOR UPDATE;
  END IF;
  IF v_fighter.id IS NULL THEN
    INSERT INTO public.combat2_departure_request(request_id,character_id,origin_node_id,destination_node_id,direction,cost,status,resolved_at)
      VALUES(_request_id,_character_id,v_character.current_node_id,_destination_node_id,v_connection->>'direction',v_cost,'moved',now());
    PERFORM set_config('app.combat2_depart_authorized','true',true);
    UPDATE public.characters SET current_node_id=_destination_node_id,mp=mp-v_cost
      WHERE id=_character_id AND current_node_id=v_character.current_node_id AND hp>0 AND mp>=v_cost;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='combat2_depart_fence_failed'; END IF;
    RETURN jsonb_build_object('ok',true,'kind','moved','request_id',_request_id,
      'origin_node_id',v_character.current_node_id,'destination_node_id',_destination_node_id,'cost',v_cost,'resource_kind','mp');
  END IF;

  IF NOT public.combat_mode_is_open() THEN RETURN jsonb_build_object('ok',false,'kind','mode_refused','reason','maintenance'); END IF;
  IF v_fighter.exit_request_id IS NOT NULL THEN RETURN jsonb_build_object('ok',false,'kind','exit_pending'); END IF;
  INSERT INTO public.combat2_departure_request(request_id,character_id,origin_node_id,destination_node_id,
    direction,encounter_id,fighter_id,fighter_entry_seq,arrival_group_id,cost,status)
  VALUES(_request_id,_character_id,v_character.current_node_id,_destination_node_id,v_connection->>'direction',v_encounter.id,
    v_fighter.id,v_fighter.entry_seq,v_fighter.arrival_group_id,v_cost,'queued');
  INSERT INTO public.node_pending_event(encounter_id,event_type,actor_character_id,payload,request_id)
  VALUES(v_encounter.id,'fighter_depart_requested',_character_id,jsonb_build_object(
    'departure_request_id',_request_id,'fighter_id',v_fighter.id,'entry_seq',v_fighter.entry_seq,
    'arrival_group_id',v_fighter.arrival_group_id,'origin_node_id',v_character.current_node_id,
    'destination_node_id',_destination_node_id,'cost',v_cost,'resource_kind','mp'),_request_id)
  RETURNING id INTO v_event;
  UPDATE public.node_fighter SET exit_request_id=v_event,updated_at=now() WHERE id=v_fighter.id;
  UPDATE public.node_intent SET status='rejected',reject_reason='exit_pending'
    WHERE encounter_id=v_encounter.id AND character_id=_character_id AND status='pending';
  UPDATE public.node_encounter SET state_version=state_version+1,claim_token=NULL,claimed_tick=NULL,
    claim_expires_at=NULL,next_due_at=LEAST(next_due_at,now()),updated_at=now()
    WHERE id=v_encounter.id RETURNING state_version INTO v_version;
  RETURN jsonb_build_object('ok',true,'kind','queued','request_id',_request_id,'event_id',v_event,
    'origin_node_id',v_character.current_node_id,'destination_node_id',_destination_node_id,
    'cost',v_cost,'resource_kind','mp','state_version',v_version);
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_depart_without_immediate_transition(_character_id uuid, _destination_node_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE origin uuid; locked_node uuid;
BEGIN
  SELECT current_node_id INTO origin FROM public.characters WHERE id=_character_id;
  IF NOT public.combat2_movement_scope_eligible(origin,_destination_node_id) THEN
    RETURN jsonb_build_object('ok',false,'kind','scope_refused','reason','destination_not_enabled');
  END IF;
  FOR locked_node IN SELECT node_id FROM (VALUES(origin),(_destination_node_id)) nodes(node_id)
    WHERE node_id IS NOT NULL GROUP BY node_id ORDER BY node_id
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('combat_enter_node:'||locked_node::text,0));
  END LOOP;
  RETURN public.combat2_depart_without_canary_gate(_character_id,_destination_node_id,_request_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_depart(_character_id uuid, _destination_node_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE result jsonb;
BEGIN
  result:=public.combat2_depart_without_immediate_transition(_character_id,_destination_node_id,_request_id);
  IF result->>'ok'='true' AND result->>'kind' IN('queued','already_queued') THEN
    RETURN public.combat2_finish_immediate_departure(_request_id);
  END IF;
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_finish_immediate_departure(_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  d public.combat2_departure_request;
  e public.node_encounter;
  c public.characters;
  f public.node_fighter;
BEGIN
  SELECT * INTO d FROM public.combat2_departure_request WHERE request_id=_request_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'kind','departure_not_found'); END IF;
  IF d.status='moved' THEN
    RETURN jsonb_build_object('ok',true,'kind','already_moved','request_id',d.request_id,
      'origin_node_id',d.origin_node_id,'destination_node_id',d.destination_node_id,
      'cost',d.cost,'resource_kind',d.resource_kind);
  ELSIF d.status='dead' THEN
    RETURN jsonb_build_object('ok',false,'kind','dead');
  END IF;

  SELECT * INTO e FROM public.node_encounter WHERE id=d.encounter_id FOR UPDATE;
  SELECT * INTO c FROM public.characters WHERE id=d.character_id FOR UPDATE;
  SELECT * INTO f FROM public.node_fighter WHERE id=d.fighter_id FOR UPDATE;
  SELECT * INTO d FROM public.combat2_departure_request WHERE request_id=_request_id FOR UPDATE;
  IF d.status='moved' THEN
    RETURN jsonb_build_object('ok',true,'kind','already_moved','request_id',d.request_id,
      'origin_node_id',d.origin_node_id,'destination_node_id',d.destination_node_id,
      'cost',d.cost,'resource_kind',d.resource_kind);
  ELSIF d.status='dead' THEN
    RETURN jsonb_build_object('ok',false,'kind','dead');
  END IF;
  IF c.id IS NULL OR c.hp<=0 THEN
    UPDATE public.combat2_departure_request SET status='dead',resolved_tick=e.tick,resolved_at=clock_timestamp()
      WHERE request_id=d.request_id AND status='queued';
    RETURN jsonb_build_object('ok',false,'kind','dead');
  END IF;
  IF e.id IS NULL OR e.status<>'active' OR c.current_node_id IS DISTINCT FROM d.origin_node_id
     OR f.id IS NULL OR NOT f.present OR f.encounter_id IS DISTINCT FROM d.encounter_id
     OR f.entry_seq IS DISTINCT FROM d.fighter_entry_seq THEN
    RETURN jsonb_build_object('ok',false,'kind','stale_departure');
  END IF;

  -- Fence every origin-side commit before changing participation.
  UPDATE public.node_encounter SET state_version=state_version+1,claim_token=NULL,
    claimed_tick=NULL,claim_expires_at=NULL,intent_cutoff_seq=NULL,updated_at=clock_timestamp()
    WHERE id=e.id;
  UPDATE public.node_intent SET status='rejected',reject_reason='departed'
    WHERE encounter_id=e.id AND status='pending'
      AND (character_id=d.character_id OR target_character_id=d.character_id);
  UPDATE public.node_pending_event SET consumed_at=clock_timestamp(),consumed_tick=e.tick
    WHERE encounter_id=e.id AND request_id=d.request_id
      AND event_type='fighter_depart_requested' AND consumed_at IS NULL;

  -- Character-targeted encounter state (including autoattack and stance
  -- reservations) cannot follow the fighter. Creature-targeted effects sourced
  -- by the character intentionally remain processable offscreen.
  DELETE FROM public.node_effect
    WHERE encounter_id=e.id AND target_character_id=d.character_id;
  UPDATE public.node_fighter SET present=false,left_at=COALESCE(left_at,clock_timestamp()),
    exit_request_id=NULL,updated_at=clock_timestamp()
    WHERE id=f.id AND present;
  PERFORM public.combat2_refresh_tanks(e.id);

  PERFORM set_config('app.combat2_depart_authorized','true',true);
  UPDATE public.characters SET current_node_id=d.destination_node_id,mp=mp-d.cost
    WHERE id=d.character_id AND current_node_id=d.origin_node_id AND hp>0 AND mp>=d.cost;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='combat2_immediate_depart_fence_failed'; END IF;
  UPDATE public.combat2_departure_request SET status='moved',resolved_tick=e.tick,resolved_at=clock_timestamp()
    WHERE request_id=d.request_id AND status='queued';
  RETURN jsonb_build_object('ok',true,'kind','moved','request_id',d.request_id,
    'origin_node_id',d.origin_node_id,'destination_node_id',d.destination_node_id,
    'cost',d.cost,'resource_kind',d.resource_kind);
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_finish_immediate_party_departure(_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.combat2_party_departure_request; m public.combat2_party_departure_member;
  outcome jsonb; outcomes jsonb;
BEGIN
  SELECT * INTO r FROM public.combat2_party_departure_request WHERE request_id=_request_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'kind','departure_not_found'); END IF;
  IF r.status='completed' THEN RETURN public.combat2_party_departure_result(_request_id); END IF;
  FOR m IN SELECT * FROM public.combat2_party_departure_member WHERE request_id=_request_id ORDER BY movement_order FOR UPDATE LOOP
    IF m.status='queued' THEN
      outcome:=public.combat2_finish_immediate_departure(m.departure_request_id);
      IF outcome->>'ok'<>'true' THEN RAISE EXCEPTION 'combat2_party_immediate_depart_failed: %',outcome->>'kind'; END IF;
    ELSE
      PERFORM set_config('app.combat2_depart_authorized','true',true);
      UPDATE public.characters SET current_node_id=r.destination_node_id,mp=mp-m.cost
        WHERE id=m.character_id AND current_node_id=r.origin_node_id AND hp>0 AND mp>=m.cost;
      IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='combat2_party_immediate_depart_fence_failed'; END IF;
    END IF;
    UPDATE public.combat2_party_departure_member SET status='moved',resolved_at=clock_timestamp()
      WHERE request_id=_request_id AND character_id=m.character_id;
  END LOOP;
  SELECT jsonb_agg(jsonb_build_object('character_id',character_id,'display_name',display_name,
    'order',movement_order,'status',status,'cost',cost) ORDER BY movement_order)
    INTO outcomes FROM public.combat2_party_departure_member WHERE request_id=_request_id;
  UPDATE public.combat2_party_departure_request SET status='completed',result=outcomes,resolved_at=clock_timestamp()
    WHERE request_id=_request_id;
  RETURN jsonb_build_object('ok',true,'kind','moved','request_id',_request_id,
    'origin_node_id',r.origin_node_id,'destination_node_id',r.destination_node_id,
    'cost',0,'resource_kind','mp','members',outcomes);
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_hostile_action(_character_id uuid, _intent_kind text, _ability_key text, _target_creature_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_node uuid; v_class text;
  v_entry jsonb; v_intent jsonb; v_target_type text; v_activation text;
  v_existing public.node_intent; v_existing_fighter public.node_fighter;
BEGIN
  IF _request_id IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','invalid_request','reason','request_id_required'); END IF;
  IF NOT public.owns_character(_character_id) THEN RETURN jsonb_build_object('ok',false,'kind','not_authorized'); END IF;
  SELECT current_node_id,class INTO v_node,v_class FROM public.characters WHERE id=_character_id AND hp>0;
  IF v_node IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','not_living_at_node'); END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('combat_enter_node:'||v_node::text,0));
  SELECT c.current_node_id,c.class INTO v_node,v_class FROM public.characters c
    WHERE c.id=_character_id AND c.hp>0 AND c.current_node_id=v_node;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'kind','node_changed'); END IF;

  -- A request that already reached the authoritative intent ledger must replay
  -- or conflict there before current catalogue classification is considered.
  -- The node advisory lock serializes this lookup with both this function and
  -- the public combat_intent wrapper without widening the lock order.
  SELECT * INTO v_existing FROM public.node_intent i WHERE i.request_id=_request_id;
  IF FOUND THEN
    v_intent:=public.combat_intent(v_existing.encounter_id,_character_id,_intent_kind,
      _ability_key,NULL,_target_creature_id,NULL,_request_id);
    IF v_intent->>'ok' IS DISTINCT FROM 'true' THEN RETURN v_intent; END IF;
    SELECT * INTO v_existing_fighter FROM public.node_fighter f
      WHERE f.encounter_id=v_existing.encounter_id AND f.character_id=_character_id;
    RETURN v_intent||jsonb_build_object('encounter_id',v_existing.encounter_id,
      'fighter_id',v_existing_fighter.id,'entry_seq',v_existing_fighter.entry_seq,
      'entry_kind','already_entered');
  END IF;

  IF _intent_kind NOT IN ('basic_attack','ability')
     OR (_intent_kind='basic_attack' AND _ability_key IS NOT NULL)
     OR (_intent_kind='ability' AND _ability_key IS NULL) THEN
    RETURN jsonb_build_object('ok',false,'kind','non_hostile_action');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.creatures c WHERE c.id=_target_creature_id AND c.node_id=v_node AND c.is_alive) THEN
    RETURN jsonb_build_object('ok',false,'kind','invalid_target');
  END IF;
  IF _intent_kind='ability' THEN
    SELECT a.target_type,a.activation_mode INTO v_target_type,v_activation
    FROM public.class_ability_assignments ca
    JOIN public.abilities a ON a.id=ca.ability_id
    WHERE ca.class_key=v_class AND ca.status='active' AND a.status='active'
      AND (ca.class_ability_key=_ability_key OR a.ability_key=_ability_key)
    ORDER BY (ca.class_ability_key=_ability_key) DESC,ca.unlock_level DESC,a.id
    LIMIT 1;
    IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'kind','ability_unavailable'); END IF;
    IF v_target_type<>'enemy' OR v_activation='stance' THEN
      RETURN jsonb_build_object('ok',false,'kind','non_hostile_action');
    END IF;
  END IF;

  BEGIN
    v_entry:=public.combat_enter_without_engagement_gate(_character_id,_request_id);
    IF NOT ((v_entry->>'ok'='true' AND v_entry->>'kind' IN ('entered','reentered','already_entered'))
      OR (v_entry->>'ok'='false' AND v_entry->>'kind'='already_present')) THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE=COALESCE(v_entry->>'kind','entry_refused');
    END IF;
    v_intent:=public.combat_intent((v_entry->>'encounter_id')::uuid,_character_id,_intent_kind,
      _ability_key,NULL,_target_creature_id,NULL,_request_id);
    IF v_intent->>'ok' IS DISTINCT FROM 'true' THEN
      RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE=COALESCE(v_intent->>'kind','intent_refused');
    END IF;
  EXCEPTION WHEN SQLSTATE 'P0001' THEN
    RETURN jsonb_build_object('ok',false,'kind',SQLERRM);
  END;
  RETURN v_intent||jsonb_build_object('encounter_id',v_entry->>'encounter_id',
    'fighter_id',v_entry->>'fighter_id','entry_seq',(v_entry->>'entry_seq')::bigint,
    'entry_kind',v_entry->>'kind');
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_party_depart_without_canary_gate(_leader_character_id uuid, _destination_node_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE caller uuid:=auth.uid(); leader public.characters; p public.parties; prior public.combat2_party_departure_request;
 conn jsonb; encounter public.node_encounter; mover record; fighter public.node_fighter; cap integer; bag numeric; cost integer;
 ordinal integer:=0; child uuid; event_id uuid; queued integer:=0; outcomes jsonb; mover_ids uuid[]; locked_count integer; locked_origin uuid;
BEGIN
 IF caller IS NULL OR _leader_character_id IS NULL OR _destination_node_id IS NULL OR _request_id IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','not_authorized'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('party-lifecycle',0));
 PERFORM pg_advisory_xact_lock(hashtextextended('combat2_party_depart_request:'||_request_id::text,0));
 SELECT * INTO prior FROM public.combat2_party_departure_request WHERE request_id=_request_id;
 IF FOUND THEN
  IF prior.caller_id<>caller OR prior.leader_character_id<>_leader_character_id OR prior.destination_node_id<>_destination_node_id THEN RETURN jsonb_build_object('ok',false,'kind','request_id_conflict'); END IF;
  RETURN public.combat2_party_departure_result(_request_id);
 END IF;
 SELECT * INTO leader FROM public.characters WHERE id=_leader_character_id AND user_id=caller;
 SELECT * INTO p FROM public.parties WHERE leader_id=_leader_character_id;
 IF leader.id IS NULL OR p.id IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','leader_required'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('combat_enter_node:'||leader.current_node_id::text,0));
 PERFORM 1 FROM public.node_encounter WHERE node_id IN(leader.current_node_id,_destination_node_id) ORDER BY id FOR UPDATE;
 SELECT * INTO encounter FROM public.node_encounter WHERE node_id=leader.current_node_id AND status='active' FOR UPDATE;
 -- ENG-MOVE-001: the immediate owner fences the captured claim below.

 -- Freeze the complete authoritative mover set without taking a character row
 -- lock, then acquire the entire set in the same UUID order as settlement.
 locked_origin:=leader.current_node_id;
 SELECT array_agg(candidate.id ORDER BY candidate.id) INTO mover_ids FROM (
  SELECT c.id FROM public.party_members pm JOIN public.characters c ON c.id=pm.character_id
   WHERE pm.party_id=p.id AND pm.status='accepted' AND pm.is_following
     AND c.id<>leader.id AND c.current_node_id=leader.current_node_id AND c.hp>0
  UNION ALL SELECT leader.id
 ) candidate;
 PERFORM 1 FROM public.characters c WHERE c.id=ANY(mover_ids) ORDER BY c.id FOR UPDATE;
 GET DIAGNOSTICS locked_count=ROW_COUNT;
 IF locked_count<>cardinality(mover_ids) THEN
  RETURN jsonb_build_object('ok',false,'kind','party_changed');
 END IF;
 SELECT * INTO leader FROM public.characters WHERE id=_leader_character_id;
 IF leader.id IS NULL OR leader.user_id<>caller OR leader.current_node_id IS DISTINCT FROM locked_origin THEN
  RETURN jsonb_build_object('ok',false,'kind','party_changed');
 END IF;
 IF leader.hp<=0 THEN RETURN jsonb_build_object('ok',false,'kind','dead','member',leader.name); END IF;
 IF EXISTS (
  SELECT 1 FROM unnest(mover_ids) included(id) JOIN public.characters c ON c.id=included.id
  WHERE c.id<>leader.id AND (c.current_node_id IS DISTINCT FROM leader.current_node_id OR c.hp<=0 OR NOT EXISTS (
    SELECT 1 FROM public.party_members pm WHERE pm.party_id=p.id AND pm.character_id=c.id
      AND pm.status='accepted' AND pm.is_following
  ))
 ) THEN RETURN jsonb_build_object('ok',false,'kind','party_changed'); END IF;
 SELECT cconn INTO conn FROM public.nodes n CROSS JOIN LATERAL jsonb_array_elements(COALESCE(n.connections,'[]')) cconn
  WHERE n.id=leader.current_node_id AND cconn->>'node_id'=_destination_node_id::text LIMIT 1;
 IF conn IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','not_adjacent'); END IF;
 IF COALESCE((conn->>'hidden')::boolean,false) AND NOT public.hidden_connection_is_open(
   leader.current_node_id,_destination_node_id,conn->>'direction') THEN RETURN jsonb_build_object('ok',false,'kind','unsupported_transition','reason','hidden'); END IF;
 IF COALESCE(conn->>'direction','')='' THEN RETURN jsonb_build_object('ok',false,'kind','unsupported_transition','reason','missing_direction'); END IF;

 -- Static all-or-none pass. Accepted followers are ordered by joined_at then character UUID; leader is forced last.
 FOR mover IN
  SELECT c.*,pm.joined_at,false leader_last FROM public.party_members pm JOIN public.characters c ON c.id=pm.character_id
   WHERE pm.party_id=p.id AND pm.status='accepted' AND pm.is_following AND c.id<>leader.id AND c.current_node_id=leader.current_node_id AND c.hp>0
  UNION ALL SELECT leader.*,NULL::timestamptz,true
  ORDER BY leader_last,joined_at,id
 LOOP
  -- Every included character row is already held by the canonical UUID lock set.
  IF COALESCE((conn->>'locked')::boolean,false) AND NOT EXISTS(SELECT 1 FROM public.character_inventory ci JOIN public.items i ON i.id=ci.item_id
    WHERE ci.character_id=mover.id AND lower(i.name)=lower(COALESCE(conn->>'lock_key',''))) THEN
   RETURN jsonb_build_object('ok',false,'kind','missing_required_key','member',mover.name);
  END IF;
  cap:=GREATEST(12+FLOOR((COALESCE(mover.str,10)-10)/2.0)::int,10);
  SELECT COALESCE(SUM(CASE WHEN i.item_type='consumable' THEN 1.0/3.0 ELSE 1.0 END),0) INTO bag
   FROM public.character_inventory ci JOIN public.items i ON i.id=ci.item_id WHERE ci.character_id=mover.id AND ci.equipped_slot IS NULL;
  cost:=5+GREATEST(0,CEIL(bag)::int-cap)*3;
  IF COALESCE(mover.mp,0)<cost THEN RETURN jsonb_build_object('ok',false,'kind','insufficient_resource','member',mover.name,'resource_kind','mp'); END IF;
  IF EXISTS(SELECT 1 FROM public.combat2_departure_request d WHERE d.character_id=mover.id AND d.status='queued') THEN
   RETURN jsonb_build_object('ok',false,'kind','movement_already_pending','member',mover.name); END IF;
 END LOOP;

 INSERT INTO public.combat2_party_departure_request VALUES(_request_id,caller,leader.id,p.id,leader.current_node_id,_destination_node_id,conn->>'direction','queued',NULL,now(),NULL);
 FOR mover IN
  SELECT c.*,pm.joined_at,false leader_last FROM public.party_members pm JOIN public.characters c ON c.id=pm.character_id
   WHERE pm.party_id=p.id AND pm.status='accepted' AND pm.is_following AND c.id<>leader.id AND c.current_node_id=leader.current_node_id AND c.hp>0
  UNION ALL SELECT leader.*,NULL::timestamptz,true ORDER BY leader_last,joined_at,id
 LOOP
  ordinal:=ordinal+1; child:=(substr(md5(_request_id::text||mover.id::text),1,8)||'-'||substr(md5(_request_id::text||mover.id::text),9,4)||'-4'||substr(md5(_request_id::text||mover.id::text),14,3)||'-8'||substr(md5(_request_id::text||mover.id::text),18,3)||'-'||substr(md5(_request_id::text||mover.id::text),21,12))::uuid;
  cap:=GREATEST(12+FLOOR((COALESCE(mover.str,10)-10)/2.0)::int,10);
  SELECT COALESCE(SUM(CASE WHEN i.item_type='consumable' THEN 1.0/3.0 ELSE 1.0 END),0) INTO bag FROM public.character_inventory ci JOIN public.items i ON i.id=ci.item_id WHERE ci.character_id=mover.id AND ci.equipped_slot IS NULL;
  cost:=5+GREATEST(0,CEIL(bag)::int-cap)*3;
  fighter:=NULL; IF encounter.id IS NOT NULL THEN SELECT * INTO fighter FROM public.node_fighter WHERE encounter_id=encounter.id AND character_id=mover.id AND present FOR UPDATE; END IF;
  INSERT INTO public.combat2_party_departure_member VALUES(_request_id,mover.id,mover.name,ordinal,child,encounter.id,fighter.id,fighter.entry_seq,fighter.arrival_group_id,cost,CASE WHEN fighter.id IS NULL THEN 'waiting' ELSE 'queued' END,NULL,NULL);
  IF fighter.id IS NOT NULL THEN
   queued:=queued+1;
   INSERT INTO public.combat2_departure_request(request_id,character_id,origin_node_id,destination_node_id,direction,encounter_id,fighter_id,fighter_entry_seq,arrival_group_id,cost,status)
    VALUES(child,mover.id,leader.current_node_id,_destination_node_id,conn->>'direction',encounter.id,fighter.id,fighter.entry_seq,fighter.arrival_group_id,cost,'queued');
   INSERT INTO public.node_pending_event(encounter_id,event_type,actor_character_id,payload,request_id,occurred_at)
    VALUES(encounter.id,'fighter_depart_requested',mover.id,jsonb_build_object('departure_request_id',child,'fighter_id',fighter.id,'entry_seq',fighter.entry_seq,'arrival_group_id',fighter.arrival_group_id,
     'origin_node_id',leader.current_node_id,'destination_node_id',_destination_node_id,'cost',cost,'resource_kind','mp'),child,clock_timestamp()+ordinal*interval '1 microsecond') RETURNING id INTO event_id;
   UPDATE public.node_fighter SET exit_request_id=event_id,updated_at=now() WHERE id=fighter.id;
   UPDATE public.node_intent SET status='rejected',reject_reason='exit_pending' WHERE encounter_id=encounter.id AND character_id=mover.id AND status='pending';
  END IF;
 END LOOP;
 IF queued=0 THEN
  FOR mover IN SELECT * FROM public.combat2_party_departure_member WHERE request_id=_request_id ORDER BY movement_order FOR UPDATE LOOP
   PERFORM set_config('app.combat2_depart_authorized','true',true);
   UPDATE public.characters SET current_node_id=_destination_node_id,mp=mp-mover.cost WHERE id=mover.character_id AND current_node_id=leader.current_node_id AND hp>0 AND mp>=mover.cost;
   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='combat2_party_depart_fence_failed'; END IF;
   UPDATE public.combat2_party_departure_member SET status='moved',resolved_at=now() WHERE request_id=_request_id AND character_id=mover.character_id;
  END LOOP;
  UPDATE public.combat2_party_departure_request SET status='completed',resolved_at=now() WHERE request_id=_request_id;
 ELSE
  UPDATE public.node_encounter SET state_version=state_version+1,claim_token=NULL,claimed_tick=NULL,claim_expires_at=NULL,next_due_at=LEAST(next_due_at,now()),updated_at=now() WHERE id=encounter.id;
 END IF;
 SELECT jsonb_agg(jsonb_build_object('character_id',character_id,'display_name',display_name,'order',movement_order,'status',status,'cost',cost) ORDER BY movement_order) INTO outcomes FROM public.combat2_party_departure_member WHERE request_id=_request_id;
 RETURN jsonb_build_object('ok',true,'kind',CASE WHEN queued=0 THEN 'moved' ELSE 'queued' END,'request_id',_request_id,'origin_node_id',leader.current_node_id,
  'destination_node_id',_destination_node_id,'cost',0,'resource_kind','mp','members',outcomes);
EXCEPTION WHEN unique_violation THEN RETURN jsonb_build_object('ok',false,'kind','movement_already_pending');
 WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'kind','party_movement_failed');
END $function$

CREATE OR REPLACE FUNCTION public.combat2_party_depart_without_immediate_transition(_leader_character_id uuid, _destination_node_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE origin uuid; locked_node uuid;
BEGIN
  SELECT current_node_id INTO origin FROM public.characters WHERE id=_leader_character_id;
  IF NOT public.combat2_movement_scope_eligible(origin,_destination_node_id) THEN
    RETURN jsonb_build_object('ok',false,'kind','scope_refused','reason','destination_not_enabled');
  END IF;
  FOR locked_node IN SELECT node_id FROM (VALUES(origin),(_destination_node_id)) nodes(node_id)
    WHERE node_id IS NOT NULL GROUP BY node_id ORDER BY node_id
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('combat_enter_node:'||locked_node::text,0));
  END LOOP;
  RETURN public.combat2_party_depart_without_canary_gate(_leader_character_id,_destination_node_id,_request_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_party_depart(_leader_character_id uuid, _destination_node_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE result jsonb;
BEGIN
  result:=public.combat2_party_depart_without_immediate_transition(_leader_character_id,_destination_node_id,_request_id);
  IF result->>'ok'='true' AND result->>'kind' IN('queued','already_queued') THEN
    RETURN public.combat2_finish_immediate_party_departure(_request_id);
  END IF;
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.combat2_party_departure_finalize()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE parent uuid; m public.combat2_party_departure_member; outcomes jsonb; did_move boolean;
BEGIN
 SELECT request_id INTO parent FROM public.combat2_party_departure_member WHERE departure_request_id=NEW.request_id;
 IF parent IS NULL THEN RETURN NEW; END IF;
 UPDATE public.combat2_party_departure_member SET status=NEW.status,resolved_tick=NEW.resolved_tick,resolved_at=NEW.resolved_at
  WHERE departure_request_id=NEW.request_id AND status='queued' AND NEW.status IN('moved','dead');
 IF EXISTS(SELECT 1 FROM public.combat2_party_departure_member WHERE request_id=parent AND status='queued') THEN RETURN NEW; END IF;
 FOR m IN SELECT * FROM public.combat2_party_departure_member WHERE request_id=parent AND status='waiting' ORDER BY movement_order FOR UPDATE LOOP
  PERFORM set_config('app.combat2_depart_authorized','true',true);
  UPDATE public.characters c SET current_node_id=r.destination_node_id,mp=c.mp-m.cost
   FROM public.combat2_party_departure_request r WHERE r.request_id=parent AND c.id=m.character_id
    AND c.current_node_id=r.origin_node_id AND c.hp>0 AND c.mp>=m.cost;
  did_move:=FOUND;
  UPDATE public.combat2_party_departure_member SET status=CASE WHEN did_move THEN 'moved' ELSE 'remaining' END,resolved_at=now()
   WHERE request_id=parent AND character_id=m.character_id;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('character_id',character_id,'display_name',display_name,'order',movement_order,'status',status,'cost',cost) ORDER BY movement_order)
  INTO outcomes FROM public.combat2_party_departure_member WHERE request_id=parent;
 UPDATE public.combat2_party_departure_request SET status='completed',result=outcomes,resolved_at=now() WHERE request_id=parent;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.combat2_party_tank_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_encounter uuid;
BEGIN
  FOR v_encounter IN SELECT DISTINCT g.encounter_id FROM public.node_arrival_group g
    WHERE g.party_id = NEW.id AND g.active LOOP
    UPDATE public.node_encounter SET state_version = state_version + 1,
      claim_token = NULL, claimed_tick = NULL, claim_expires_at = NULL, updated_at = now()
      WHERE id = v_encounter;
    PERFORM public.combat2_refresh_tanks(v_encounter);
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.node_tick_claim_without_character_stances(_node_id uuid, _lease_ms integer DEFAULT 5000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE source jsonb; creatures jsonb;
BEGIN
 source:=public.node_tick_claim_without_boss_timing(_node_id,_lease_ms);
 IF source->>'kind'<>'claimed' THEN RETURN source; END IF;
 SELECT coalesce(jsonb_agg(x.elem||jsonb_build_object('pending_action',CASE WHEN nc.pending_action IS NULL THEN NULL ELSE
  jsonb_build_object('ability_key',nc.pending_action->>'ability_key','ability_label',nc.pending_action->>'ability_label',
   'started_at_tick',(nc.pending_action->>'started_at_tick')::bigint,'resolve_at_tick',(nc.pending_action->>'resolve_at_tick')::bigint,
   'target_mode',nc.pending_action->>'target_mode','primary_magnitude',(nc.pending_action->>'primary_magnitude')::numeric,
   'secondary_magnitude',(nc.pending_action->>'secondary_magnitude')::numeric,'damage_type',nc.pending_action->'damage_type',
   'target_fighter_id',NULL,'target_character_id',NULL,'target_entry_seq',NULL) END) ORDER BY x.ord),'[]'::jsonb)
 INTO creatures FROM jsonb_array_elements(source#>'{snapshot,creatures}') WITH ORDINALITY x(elem,ord)
 JOIN public.node_creature nc ON nc.id=(x.elem->>'id')::uuid;
 source:=jsonb_set(source,'{snapshot,creatures}',creatures);
 source:=jsonb_set(source,'{snapshot,boss_cooldowns}',coalesce((SELECT jsonb_agg(to_jsonb(cd) ORDER BY cd.node_creature_id,cd.spawn_seq,cd.ability_key)
  FROM public.node_boss_ability_cooldown cd WHERE cd.encounter_id=(source->>'encounter_id')::uuid),'[]'::jsonb));
 RETURN source;
END $function$

CREATE OR REPLACE FUNCTION public.node_tick_claim(_node_id uuid, _lease_ms integer DEFAULT 5000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE out jsonb; eid uuid; stances jsonb; transitions jsonb;
BEGIN
 out:=public.node_tick_claim_without_character_stances(_node_id,_lease_ms);
 IF out->>'ok'<>'true' OR out->>'kind'<>'claimed' THEN RETURN out; END IF;
 eid:=(out#>>'{snapshot,encounter,id}')::uuid;
 SELECT coalesce(jsonb_agg(jsonb_build_object('character_id',s.character_id,'ability_key',s.ability_key,
   'reserve_pct',s.reserve_pct,'version',s.version,'state',s.state,'activated_at',s.activated_at)
   ORDER BY s.character_id,s.ability_key),'[]'::jsonb) INTO stances
 FROM public.character_stance s JOIN public.node_fighter f ON f.character_id=s.character_id
 WHERE f.encounter_id=eid AND f.present;
 SELECT coalesce(jsonb_agg(jsonb_build_object('request_id',r.request_id,'intent_id',r.intent_id,
   'character_id',r.character_id,'ability_key',r.ability_key,'action',r.action) ORDER BY r.intent_id),'[]'::jsonb)
 INTO transitions FROM public.character_stance_request r WHERE r.encounter_id=eid AND r.committed_at IS NULL;
 RETURN jsonb_set(jsonb_set(out,'{snapshot,character_stances}',stances,true),'{snapshot,stance_transitions}',transitions,true);
END $function$

CREATE OR REPLACE FUNCTION public.party_mutate(_actor_character_id uuid, _operation text, _party_id uuid, _target_character_id uuid, _membership_id uuid, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE caller uuid:=auth.uid(); prior public.party_operation_request; actor public.characters; p public.parties;
 member public.party_members; created_party uuid; result jsonb; member_count integer;
BEGIN
 IF caller IS NULL THEN RETURN jsonb_build_object('ok',false,'kind','not_authorized'); END IF;
 IF _request_id IS NULL OR _actor_character_id IS NULL OR _operation IS NULL
  THEN RETURN jsonb_build_object('ok',false,'kind','invalid_shape'); END IF;
 -- Global order: lifecycle advisory lock, request row, actor row, party row, membership rows.
 PERFORM pg_advisory_xact_lock(hashtextextended('party-lifecycle',0));
 SELECT * INTO prior FROM public.party_operation_request WHERE request_id=_request_id;
 IF FOUND THEN
  IF prior.caller_id IS DISTINCT FROM caller OR prior.actor_character_id<>_actor_character_id OR prior.operation<>_operation
   OR prior.party_id IS DISTINCT FROM _party_id OR prior.target_character_id IS DISTINCT FROM _target_character_id
   OR prior.membership_id IS DISTINCT FROM _membership_id THEN RETURN jsonb_build_object('ok',false,'kind','request_id_conflict'); END IF;
  RETURN COALESCE(prior.result,jsonb_build_object('ok',false,'kind','request_in_progress'));
 END IF;
 IF _operation NOT IN('create','invite','accept','decline','cancel','leave','kick','disband','set_tank','follow','stop_following')
  THEN RETURN jsonb_build_object('ok',false,'kind','unknown_operation'); END IF;
 INSERT INTO public.party_operation_request(request_id,caller_id,actor_character_id,operation,party_id,target_character_id,membership_id)
  VALUES(_request_id,caller,_actor_character_id,_operation,_party_id,_target_character_id,_membership_id);
 SELECT * INTO actor FROM public.characters WHERE id=_actor_character_id AND user_id=caller FOR UPDATE;
 IF NOT FOUND THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','not_authorized')); END IF;
 IF actor.hp<=0 THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','actor_dead')); END IF;

 IF _operation='create' THEN
  IF _party_id IS NOT NULL OR _target_character_id IS NOT NULL OR _membership_id IS NOT NULL
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_shape')); END IF;
  IF EXISTS(SELECT 1 FROM public.party_members WHERE character_id=actor.id AND status='accepted') OR EXISTS(SELECT 1 FROM public.parties WHERE leader_id=actor.id)
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','already_in_party')); END IF;
  INSERT INTO public.parties(leader_id,tank_id) VALUES(actor.id,actor.id) RETURNING id INTO created_party;
  INSERT INTO public.party_members(party_id,character_id,status,is_following) VALUES(created_party,actor.id,'accepted',false);
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','party_created','party_id',created_party));
 END IF;

 IF _operation='accept' THEN
  IF _membership_id IS NULL OR _party_id IS NOT NULL OR _target_character_id IS NOT NULL
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_shape')); END IF;
  SELECT * INTO member FROM public.party_members WHERE id=_membership_id AND character_id=actor.id FOR UPDATE;
  IF NOT FOUND OR member.status<>'pending' THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invitation_not_active')); END IF;
  IF EXISTS(SELECT 1 FROM public.party_members WHERE character_id=actor.id AND status='accepted')
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','already_in_party')); END IF;
  IF public.party_combat_mutation_blocked(member.party_id,actor.id)
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','combat_active')); END IF;
  UPDATE public.party_members SET status='accepted',joined_at=now(),is_following=false WHERE id=member.id;
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','invitation_accepted','party_id',member.party_id));
 END IF;

 IF _operation='decline' THEN
  IF _membership_id IS NULL OR _party_id IS NOT NULL OR _target_character_id IS NOT NULL
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_shape')); END IF;
  SELECT * INTO member FROM public.party_members WHERE id=_membership_id AND character_id=actor.id AND status='pending' FOR UPDATE;
  IF NOT FOUND THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','invitation_already_closed')); END IF;
  DELETE FROM public.party_members WHERE id=member.id;
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','invitation_declined'));
 END IF;

 SELECT * INTO p FROM public.parties WHERE id=_party_id FOR UPDATE;
 IF NOT FOUND THEN
  IF _operation='disband' THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','party_already_disbanded')); END IF;
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','party_not_found'));
 END IF;


 IF _operation IN('follow','stop_following') THEN
  IF _party_id IS NULL OR _target_character_id IS NOT NULL OR _membership_id IS NOT NULL
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_shape')); END IF;
  IF p.leader_id=actor.id THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','leader_cannot_follow')); END IF;
  SELECT * INTO member FROM public.party_members WHERE party_id=p.id AND character_id=actor.id AND status='accepted' FOR UPDATE;
  IF NOT FOUND THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','not_authorized')); END IF;
  IF public.party_combat_mutation_blocked(p.id,NULL)
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','combat_active')); END IF;
  UPDATE public.party_members SET is_following=(_operation='follow') WHERE id=member.id;
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind',CASE WHEN _operation='follow' THEN 'following' ELSE 'not_following' END,'party_id',p.id));
 END IF;

 IF _operation='invite' THEN
  IF _party_id IS NULL OR _target_character_id IS NULL OR _membership_id IS NOT NULL
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_shape')); END IF;
  IF p.leader_id<>actor.id THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','leader_required')); END IF;
  IF _target_character_id IS NULL OR _target_character_id=actor.id OR NOT EXISTS(SELECT 1 FROM public.characters c WHERE c.id=_target_character_id AND c.hp>0 AND c.current_node_id=actor.current_node_id)
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','target_not_available')); END IF;
  IF EXISTS(SELECT 1 FROM public.party_members WHERE character_id=_target_character_id AND status='accepted')
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','target_already_in_party')); END IF;
  SELECT * INTO member FROM public.party_members WHERE party_id=p.id AND character_id=_target_character_id AND status='pending';
  IF FOUND THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','already_invited','membership_id',member.id)); END IF;
  SELECT count(*) INTO member_count FROM public.party_members WHERE party_id=p.id;
  IF member_count>=4 THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','party_full')); END IF;
  INSERT INTO public.party_members(party_id,character_id,status,is_following) VALUES(p.id,_target_character_id,'pending',false) RETURNING * INTO member;
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','invited','membership_id',member.id));
 END IF;

 IF _operation='cancel' THEN
  IF _party_id IS NULL OR _membership_id IS NULL OR _target_character_id IS NOT NULL
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_shape')); END IF;
  IF p.leader_id<>actor.id THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','leader_required')); END IF;
  SELECT * INTO member FROM public.party_members WHERE id=_membership_id AND party_id=p.id AND status='pending' FOR UPDATE;
  IF NOT FOUND THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','invitation_already_closed')); END IF;
  DELETE FROM public.party_members WHERE id=member.id;
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','invitation_cancelled'));
 END IF;

 IF public.party_combat_mutation_blocked(p.id,NULL)
  THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','combat_active')); END IF;
 IF _operation='leave' THEN
  IF _target_character_id IS NOT NULL OR _membership_id IS NOT NULL
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_shape')); END IF;
  IF p.leader_id=actor.id THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','leader_must_disband')); END IF;
  SELECT * INTO member FROM public.party_members WHERE party_id=p.id AND character_id=actor.id AND status='accepted' FOR UPDATE;
  IF NOT FOUND THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','already_left')); END IF;
  IF p.tank_id=actor.id THEN UPDATE public.parties SET tank_id=NULL WHERE id=p.id; END IF;
  DELETE FROM public.party_members WHERE id=member.id;
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','party_left'));
 END IF;
 IF p.leader_id<>actor.id THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','leader_required')); END IF;
 IF _operation='kick' THEN
  IF _membership_id IS NOT NULL THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_shape')); END IF;
  IF _target_character_id IS NULL OR _target_character_id=actor.id THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_target')); END IF;
  SELECT * INTO member FROM public.party_members WHERE party_id=p.id AND character_id=_target_character_id AND status='accepted' FOR UPDATE;
  IF NOT FOUND THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','member_already_absent')); END IF;
  IF p.tank_id=member.character_id THEN UPDATE public.parties SET tank_id=NULL WHERE id=p.id; END IF;
  DELETE FROM public.party_members WHERE id=member.id;
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','member_kicked'));
 END IF;
 IF _operation='set_tank' THEN
  IF _membership_id IS NOT NULL THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_shape')); END IF;
  IF _target_character_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.party_members pm JOIN public.characters c ON c.id=pm.character_id
    WHERE pm.party_id=p.id AND pm.character_id=_target_character_id AND pm.status='accepted' AND c.hp>0)
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_tank')); END IF;
  UPDATE public.parties SET tank_id=_target_character_id WHERE id=p.id;
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','tank_changed'));
 END IF;
 IF _operation='disband' THEN
  IF _target_character_id IS NOT NULL OR _membership_id IS NOT NULL
   THEN RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','invalid_shape')); END IF;
  DELETE FROM public.party_members WHERE party_id=p.id;
  DELETE FROM public.parties WHERE id=p.id;
  RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',true,'kind','party_disbanded'));
 END IF;
 RETURN public.party_operation_finish(_request_id,jsonb_build_object('ok',false,'kind','unknown_operation'));
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'kind','party_operation_failed');
END $function$

CREATE OR REPLACE FUNCTION public.restrict_party_leader_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _stat_delta integer;
  _points_delta integer;
  _respec_delta integer;
  _trusted boolean;
BEGIN
  _trusted := coalesce(current_setting('app.trusted_rpc', true), '') = 'true';

  IF auth.uid() = NEW.user_id THEN
    NEW.level := OLD.level;
    NEW.xp := OLD.xp;
    NEW.user_id := OLD.user_id;

    IF NOT _trusted THEN
      NEW.race := OLD.race;
      NEW.class := OLD.class;
      NEW.is_classless := OLD.is_classless;
    END IF;

    IF OLD.soulforged_item_created = true THEN
      NEW.soulforged_item_created := true;
    END IF;

    IF NOT _trusted THEN
      NEW.soulring_tier := OLD.soulring_tier;
      NEW.soulring_inventory_id := OLD.soulring_inventory_id;
      NEW.king_slayer_at := OLD.king_slayer_at;
    END IF;

    IF NEW.gold > OLD.gold AND NOT _trusted THEN
      NEW.gold := OLD.gold;
    END IF;

    IF NOT _trusted THEN
      NEW.max_hp := OLD.max_hp;
      NEW.max_cp := OLD.max_cp;
      NEW.max_mp := OLD.max_mp;
      NEW.ac := OLD.ac;

      NEW.hp := LEAST(GREATEST(COALESCE(NEW.hp, 0), 0), OLD.max_hp);
      NEW.mp := LEAST(GREATEST(COALESCE(NEW.mp, 0), 0), OLD.max_mp);
      NEW.cp := LEAST(GREATEST(COALESCE(NEW.cp, 0), 0), OLD.max_cp);

      NEW.reserved_buffs := OLD.reserved_buffs;
      NEW.stance_state := OLD.stance_state;

      NEW.bhp_trained := OLD.bhp_trained;

      NEW.family_id := OLD.family_id;
      NEW.family_name := OLD.family_name;
      NEW.family_changed_after_creation := OLD.family_changed_after_creation;

      -- Contract state: server RPCs only.
      NEW.active_contract := OLD.active_contract;
      NEW.contracts_completed := OLD.contracts_completed;
    END IF;

    IF NEW.bhp > OLD.bhp THEN
      NEW.bhp := OLD.bhp;
    END IF;

    IF NEW.rp_total_earned > OLD.rp_total_earned THEN
      NEW.rp_total_earned := OLD.rp_total_earned;
    END IF;

    IF NEW.respec_points > OLD.respec_points THEN
      NEW.respec_points := OLD.respec_points;
    END IF;

    _stat_delta := (NEW.str - OLD.str) + (NEW.dex - OLD.dex) + (NEW.con - OLD.con)
                 + (NEW.int - OLD.int) + (NEW.wis - OLD.wis) + (NEW.cha - OLD.cha);
    _points_delta := OLD.unspent_stat_points - NEW.unspent_stat_points;
    _respec_delta := OLD.respec_points - NEW.respec_points;

    IF _respec_delta <= 0 THEN
      IF _stat_delta > 0 AND _stat_delta != _points_delta THEN
        NEW.str := OLD.str;
        NEW.dex := OLD.dex;
        NEW.con := OLD.con;
        NEW.int := OLD.int;
        NEW.wis := OLD.wis;
        NEW.cha := OLD.cha;
        NEW.unspent_stat_points := OLD.unspent_stat_points;
      END IF;
      IF NEW.unspent_stat_points > OLD.unspent_stat_points THEN
        NEW.unspent_stat_points := OLD.unspent_stat_points;
      END IF;
    END IF;

    NEW.gold := GREATEST(NEW.gold, 0);
    NEW.ac := LEAST(GREATEST(NEW.ac, 1), 100);
    NEW.max_hp := LEAST(GREATEST(NEW.max_hp, 1), 10000);
    NEW.max_cp := LEAST(GREATEST(NEW.max_cp, 0), 5000);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_character_encounter_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Node change (including nulled node_id on logout)
  IF NEW.current_node_id IS DISTINCT FROM OLD.current_node_id THEN
    DELETE FROM public.encounter_participants
    WHERE character_id = NEW.id;
    RETURN NEW;
  END IF;

  -- Death: transitioned from alive to dead
  IF OLD.hp > 0 AND NEW.hp <= 0 THEN
    DELETE FROM public.encounter_participants
    WHERE character_id = NEW.id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_wake_world_on_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
  IF NEW.last_online IS NULL THEN RETURN NEW; END IF;
  IF OLD.last_online IS NOT NULL AND NEW.last_online - OLD.last_online < interval '30 seconds' THEN
    RETURN NEW;
  END IF;
  IF public.has_role(NEW.user_id, 'overlord'::app_role) OR public.has_role(NEW.user_id, 'steward'::app_role) THEN
    RETURN NEW;
  END IF;
  PERFORM public.record_world_state();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
